import xml.parsers.expat
from html.parser import HTMLParser

xml_str = "<?xml version=\"1.0\"?><!-- comment --><root attr=\"val\"><child>text</child><empty/></root>"

class XMLDomBuilder:
    def __init__(self):
        self.p = xml.parsers.expat.ParserCreate()
        self.p.StartElementHandler = self.start_element
        self.p.EndElementHandler = self.end_element
        self.p.CharacterDataHandler = self.char_data
        self.p.CommentHandler = self.comment
        self.p.ProcessingInstructionHandler = self.pi
        self.stack = []
        self.root = None

    def start_element(self, name, attrs):
        print(f"Start: {name}, attrs: {attrs}")

    def end_element(self, name):
        print(f"End: {name}")

    def char_data(self, data):
        if data.strip():
            print(f"Text: {repr(data)}")

    def comment(self, data):
        print(f"Comment: {repr(data)}")

    def pi(self, target, data):
        print(f"PI: {target}, {data}")

    def parse(self, data):
        self.p.Parse(data)

builder = XMLDomBuilder()
builder.parse(xml_str)
