import sys, os, subprocess, json, re
import xml.parsers.expat
from html.parser import HTMLParser

class Options:
    def __init__(self):
        self.attr = None
        self.color = False
        self.compact = False
        self.depth = -1
        self.extract = None
        self.help = False
        self.html = False
        self.in_place = False
        self.indent = 2
        self.json = False
        self.no_color = False
        self.node = False
        self.query = None
        self.tab = False
        self.version = False
        self.xpath = None
        self.files = []

def parse_args(args):
    opts = Options()
    i = 0
    while i < len(args):
        arg = args[i]
        if arg == "--":
            opts.files.extend(args[i+1:])
            break
        elif arg.startswith("--"):
            if "=" in arg:
                flag, val = arg.split("=", 1)
            else:
                flag, val = arg, None

            if flag == "--help":
                opts.help = True
            elif flag == "--version":
                opts.version = True
            elif flag == "--color":
                opts.color = True
            elif flag == "--no-color":
                opts.no_color = True
            elif flag == "--compact":
                opts.compact = True
            elif flag == "--html":
                opts.html = True
            elif flag == "--in-place":
                opts.in_place = True
            elif flag == "--json":
                opts.json = True
            elif flag == "--node":
                opts.node = True
            elif flag == "--tab":
                opts.tab = True
            elif flag in ("--attr", "--depth", "--extract", "--indent", "--query", "--xpath"):
                if val is None:
                    if i + 1 < len(args):
                        i += 1
                        val = args[i]
                    else:
                        sys.stderr.write(f"Error: flag needs an argument: {flag}\n")
                        sys.exit(1)

                if flag == "--attr":
                    opts.attr = val
                elif flag == "--extract":
                    opts.extract = val
                elif flag == "--query":
                    opts.query = val
                elif flag == "--xpath":
                    opts.xpath = val
                elif flag == "--indent":
                    try:
                        opts.indent = int(val)
                    except ValueError:
                        sys.stderr.write(f'Error: invalid argument "{val}" for "--indent" flag: strconv.ParseInt: parsing "{val}": invalid syntax\n')
                        sys.exit(1)
                elif flag == "--depth":
                    try:
                        opts.depth = int(val)
                    except ValueError:
                        sys.stderr.write(f'Error: invalid argument "{val}" for "--depth" flag: strconv.ParseInt: parsing "{val}": invalid syntax\n')
                        sys.exit(1)
            else:
                sys.stderr.write(f"Error: unknown flag: {flag}\n")
                sys.exit(1)
        elif arg.startswith("-") and len(arg) > 1:
            j = 1
            while j < len(arg):
                char = arg[j]
                if char == 'h':
                    opts.help = True
                elif char == 'v':
                    opts.version = True
                elif char == 'c':
                    opts.color = True
                elif char == 'm':
                    opts.html = True
                elif char == 'i':
                    opts.in_place = True
                elif char == 'j':
                    opts.json = True
                elif char == 'n':
                    opts.node = True
                elif char in ('a', 'd', 'e', 'q', 'x'):
                    val = arg[j+1:]
                    if not val:
                        if i + 1 < len(args):
                            i += 1
                            val = args[i]
                        else:
                            sys.stderr.write(f"Error: flag needs an argument: '{char}' in -{char}\n")
                            sys.exit(1)
                    if char == 'a':
                        opts.attr = val
                    elif char == 'e':
                        opts.extract = val
                    elif char == 'q':
                        opts.query = val
                    elif char == 'x':
                        opts.xpath = val
                    elif char == 'd':
                        try:
                            opts.depth = int(val)
                        except ValueError:
                            sys.stderr.write(f'Error: invalid argument "{val}" for "--depth" flag: strconv.ParseInt: parsing "{val}": invalid syntax\n')
                            sys.exit(1)
                    break
                else:
                    sys.stderr.write(f"Error: unknown shorthand flag: '{char}' in -{arg[1:]}\n")
                    sys.exit(1)
                j += 1
        else:
            opts.files.append(arg)
        i += 1

    return opts

print("CLI parser defined")
