                    break
                else:
                    sys.stderr.write(f"Error: unknown shorthand flag: '{char}' in -{arg[1:]}\n")
                    sys.exit(1)
                j += 1
        else:
            opts.files.append(arg)
        i += 1

    return opts

# --- DOM Node Structure ---

class DOMNode:
    def __init__(self, tag="", attrs=None, text="", node_type="element"):
        self.tag = tag
        self.attrs = dict(attrs) if attrs else {}
        self.children = []
        self.parent = None
        self.node_type = node_type  # 'element', 'text', 'comment', 'cdata', 'doctype', 'pi', 'root'
        self.text = text

    def add_child(self, child):
        child.parent = self
        self.children.append(child)

    def inner_text(self):
        if self.node_type == "text":
            return self.text
        res = []
        for c in self.children:
            res.append(c.inner_text())
        return "".join(res)

    def direct_text(self):
        res = []
        for c in self.children:
            if c.node_type == "text":
                res.append(c.text)
        return "".join(res)

# --- XML Parser ---

def parse_xml(xml_str):
    root = DOMNode(node_type="root")
    stack = [root]

    def start_element(name, attrs):
        node = DOMNode(tag=name, attrs=attrs, node_type="element")
        stack[-1].add_child(node)
        stack.append(node)

    def end_element(name):
        if len(stack) > 1 and stack[-1].tag == name:
            stack.pop()

    def char_data(data):
        if data:
            node = DOMNode(text=data, node_type="text")
            stack[-1].add_child(node)

    def comment_handler(data):
        node = DOMNode(text=data, node_type="comment")
        stack[-1].add_child(node)

    def pi_handler(target, data):
        text = f"{target} {data}".strip()
        node = DOMNode(text=text, node_type="pi")
        stack[-1].add_child(node)

    def xml_decl_handler(version, encoding, standalone):
        parts = [f'version="{version}"']
        if encoding:
            parts.append(f'encoding="{encoding}"')
        if standalone != -1:
            parts.append(f'standalone="{"yes" if standalone else "no"}"')
        text = " ".join(parts)
        node = DOMNode(text=text, node_type="xml_decl")
        stack[-1].add_child(node)

    def start_doctype(name, sysid, pubid, has_internal):
        parts = [name]
        if pubid:
            parts.append(f'PUBLIC "{pubid}"')
            if sysid:
                parts.append(f'"{sysid}"')
        elif sysid:
            parts.append(f'SYSTEM "{sysid}"')
        text = " ".join(parts)
        node = DOMNode(text=text, node_type="doctype")
        stack[-1].add_child(node)

    p = xml.parsers.expat.ParserCreate()
    p.StartElementHandler = start_element
    p.EndElementHandler = end_element
    p.CharacterDataHandler = char_data
    p.CommentHandler = comment_handler
    p.ProcessingInstructionHandler = pi_handler
    p.XmlDeclHandler = xml_decl_handler
    p.StartDoctypeDeclHandler = start_doctype

    p.Parse(xml_str)
    return root

# --- HTML Parser ---

class HTMLDomBuilder(HTMLParser):
    VOID_TAGS = {
        'area', 'base', 'br', 'col', 'embed', 'hr', 'img',
        'input', 'link', 'meta', 'param', 'source', 'track', 'wbr'
    }

    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.root = DOMNode(node_type="root")
        self.stack = [self.root]

    def handle_decl(self, decl):
        node = DOMNode(text=decl, node_type="doctype")
        self.stack[-1].add_child(node)

    def handle_starttag(self, tag, attrs):
        attr_dict = dict(attrs)
        node = DOMNode(tag=tag, attrs=attr_dict, node_type="element")
        self.stack[-1].add_child(node)
        if tag.lower() not in self.VOID_TAGS:
            self.stack.append(node)

    def handle_endtag(self, tag):
        if tag.lower() in self.VOID_TAGS:
            return
        for idx in range(len(self.stack) - 1, 0, -1):
            if self.stack[idx].tag.lower() == tag.lower():
                self.stack = self.stack[:idx]
                break

    def handle_data(self, data):
        if data:
            node = DOMNode(text=data, node_type="text")
            self.stack[-1].add_child(node)

    def handle_comment(self, data):
        node = DOMNode(text=data, node_type="comment")
        self.stack[-1].add_child(node)

def parse_html(html_str):
    builder = HTMLDomBuilder()
    builder.feed(html_str)
    return builder.root

# --- Formatter ---

def format_node(node, is_html=False, indent_str="  ", level=0):
    if node.node_type == "root":
        res = []
        for c in node.children:
            formatted = format_node(c, is_html, indent_str, level)
            if formatted:
                res.append(formatted)
        return "\n".join(res) + "\n" if res else ""

    prefix = indent_str * level

    if node.node_type == "xml_decl":
        return f"{prefix}<?xml {node.text}?>"
    elif node.node_type == "doctype":
        if is_html:
            doc_text = node.text
            if doc_text.lower().startswith("doctype "):
                doc_text = "doctype " + doc_text[8:]
            return f"{prefix}<!{doc_text}>"
        return f"{prefix}<!DOCTYPE {node.text}>"
    elif node.node_type == "comment":
        return f"{prefix}<!--{node.text}-->"
    elif node.node_type == "pi":
        return f"{prefix}<?{node.text}?>"
    elif node.node_type == "text":
        return node.text

    # Element
    tag = node.tag
    attrs_str = ""
    if node.attrs:
        attr_parts = []
        for k, v in node.attrs.items():
            if is_html and v is None:
                attr_parts.append(f'{k}=""')
            else:
                attr_parts.append(f'{k}="{v}"')
        attrs_str = " " + " ".join(attr_parts)

    elem_children = [c for c in node.children if c.node_type != "text"]
    text_children = [c for c in node.children if c.node_type == "text"]

    is_void = is_html and tag.lower() in HTMLDomBuilder.VOID_TAGS

    if is_void:
        return f"{prefix}<{tag}{attrs_str}/>"

    if not node.children:
        if is_html:
            return f"{prefix}<{tag}{attrs_str}></{tag}>"
        else:
            return f"{prefix}<{tag}{attrs_str}/>"

    # Check if element contains only text
    if not elem_children and text_children:
        full_text = "".join(c.text for c in text_children)
        if "\n" not in full_text:
            return f"{prefix}<{tag}{attrs_str}>{full_text.strip()}</{tag}>"

    # For HTML formatting with mixed inline elements/text
    if is_html:
        has_block_children = any(
            c.node_type == "element" and c.tag.lower() not in ('span', 'a', 'b', 'i', 'u', 'em', 'strong', 'br')
            for c in node.children
        )
        if not has_block_children and len(node.children) <= 3:
            # Inline formatting
            inline_parts = []
            for c in node.children:
                if c.node_type == "text":
                    inline_parts.append(c.text.strip())
                elif c.node_type == "element":
                    fmt_c = format_node(c, is_html, indent_str, level + 1).strip()
                    inline_parts.append(fmt_c)
            inner_str = "".join(inline_parts)
            if len(inner_str) < 60 and "\n" not in inner_str:
                return f"{prefix}<{tag}{attrs_str}>{inner_str}</{tag}>"

    child_lines = []
    for c in node.children:
        if c.node_type == "text":
            txt = c.text.strip()
            if txt:
                child_lines.append(f"{indent_str * (level + 1)}{txt}")
        else:
            formatted = format_node(c, is_html, indent_str, level + 1)
            if formatted:
                child_lines.append(formatted)

    children_str = "\n".join(child_lines)
    return f"{prefix}<{tag}{attrs_str}>\n{children_str}\n{prefix}</{tag}>"

# --- JSON Converter ---

def dom_to_json_val(node, current_depth, max_depth):
    if max_depth >= 0 and current_depth >= max_depth:
        return node.inner_text().strip()

    elem_children = [c for c in node.children if c.node_type == "element"]

    if not node.attrs and not elem_children:
        txt = node.inner_text().strip()
        if not txt:
            return {}
        return txt

    obj = {}
    for k, v in node.attrs.items():
        obj[f"@{k}"] = v

    dir_text = node.direct_text().strip()
    if dir_text:
        obj["#text"] = dir_text

    grouped = {}
    for c in elem_children:
        grouped.setdefault(c.tag, []).append(c)

    for tag, children in grouped.items():
        child_vals = [dom_to_json_val(c, current_depth + 1, max_depth) for c in children]
        if len(child_vals) == 1:
            obj[tag] = child_vals[0]
        else:
            obj[tag] = child_vals

    return obj

def dom_to_json(root, max_depth=-1):
    elem_children = [c for c in root.children if c.node_type == "element"]
    if not elem_children:
        return {}
    if len(elem_children) == 1:
        root_elem = elem_children[0]
        return {root_elem.tag: dom_to_json_val(root_elem, 0, max_depth)}
    else:
        obj = {}
        for c in elem_children:
            obj[c.tag] = dom_to_json_val(c, 0, max_depth)
        return obj

def format_json(dict_data, compact=False, indent=2):
    if compact:
        return json.dumps(dict_data, separators=(',', ': '), sort_keys=True, ensure_ascii=False) + "\n"
    else:
        s = json.dumps(dict_data, indent=indent, sort_keys=True, ensure_ascii=False)
        def repl(m):
            prefix = m.group(1)
            spaces = m.group(2)
            return f'{prefix}\n\n{spaces}}}'
        s = re.sub(r'(\n(\s*)"[^"]+"\s*:\s*\{)\}', repl, s)
        return s + "\n"

# --- Syntax Highlighting / Colorizers ---

def colorize_json(s):
    pattern = re.compile(
        r'("(?:[^"\\]|\\.)*")\s*:'
        r'|("(?:[^"\\]|\\.)*")'
        r'|(\b-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?\b|\btrue\b|\bfalse\b|\bnull\b)'
        r'|([{}\[\]])'
    )
    def repl(m):
        if m.group(1):
            return f"\x1b[94m{m.group(1)}\x1b[0m:"
        elif m.group(2):
            return f"\x1b[32m{m.group(2)}\x1b[0m"
        elif m.group(3):
            return f"\x1b[32m{m.group(3)}\x1b[0m"
        elif m.group(4):
            return f"\x1b[33m{m.group(4)}\x1b[0m"
        return m.group(0)

    return pattern.sub(repl, s)

def colorize_xml_html(s):
    pattern = re.compile(
        r'(<!--[\s\S]*?-->)'
        r'|(<\?[\s\S]*?\?>)'
        r'|(<!doctype\s+|<!DOCTYPE\s+|<![a-zA-Z]+|<!)'
        r'|(</[a-zA-Z0-9_:-]+>)'
        r'|(</?[a-zA-Z0-9_:-]+)'
        r'|(/>|>)'
        r'|(="[^"]*"|=\'[^\']*\')'
    )
    def repl(m):
        if m.group(1):
            comment = m.group(1)
            inner = comment[4:-3]
            return f"\x1b[94m<!--\x1b[0m\x1b[94m{inner}\x1b[0m\x1b[94m-->\x1b[0m"
        elif m.group(2):
            pi = m.group(2)
            inner = pi[2:-2]
            inner_colored = re.sub(r'(="[^"]*"|=\'[^\']*\')', lambda m2: f"\x1b[32m{m2.group(1)}\x1b[0m", inner)
            return f"\x1b[33m<?\x1b[0m{inner_colored}\x1b[33m?>\x1b[0m"
        elif m.group(3):
            g3 = m.group(3)
            if g3.lower().startswith("<!doctype "):
                prefix = g3[:10]
                return f"\x1b[33m{prefix}\x1b[0m"
            if g3 in ('<!', '<!DOCTYPE', '<!doctype'):
                return '\x1b[33m<!\x1b[0m' if g3 == '<!' else f'\x1b[33m<!\x1b[0m{g3[2:]}'
            return f"\x1b[33m{g3}\x1b[0m"
        elif m.group(4):
            return f"\x1b[33m{m.group(4)}\x1b[0m"
        elif m.group(5):
            return f"\x1b[33m{m.group(5)}\x1b[0m"
        elif m.group(6):
            return f"\x1b[33m{m.group(6)}\x1b[0m"
        elif m.group(7):
            return f"\x1b[32m{m.group(7)}\x1b[0m"
        return m.group(0)

    return pattern.sub(repl, s)

# --- CSS Query Evaluator ---

def parse_css_selector(sel_str):
    groups = [g.strip() for g in sel_str.split(",") if g.strip()]
    parsed_groups = []
    for g in groups:
        tokens = re.findall(r'([>+~]|\s+)?\s*([a-zA-Z0-9_*#.:\[\]="\'^$*-]+)', g)
        chain = []
        for comb, simple in tokens:
            comb = comb.strip() if comb else (" " if chain else None)
            chain.append((comb, simple))
        if chain:
            parsed_groups.append(chain)
    return parsed_groups

def matches_simple_selector(node, simple_sel):
    if node.node_type != "element":
        return False

    if ":first-child" in simple_sel:
        simple_sel = simple_sel.replace(":first-child", "")
        if node.parent:
            siblings = [c for c in node.parent.children if c.node_type == "element"]
            if not siblings or siblings[0] != node:
                return False

    if ":last-child" in simple_sel:
        simple_sel = simple_sel.replace(":last-child", "")
        if node.parent:
            siblings = [c for c in node.parent.children if c.node_type == "element"]
            if not siblings or siblings[-1] != node:
                return False

    m_nth = re.search(r':nth-child\((\d+)\)', simple_sel)
    if m_nth:
        n = int(m_nth.group(1))
        simple_sel = re.sub(r':nth-child\(\d+\)', '', simple_sel)
        if node.parent:
            siblings = [c for c in node.parent.children if c.node_type == "element"]
            if n < 1 or n > len(siblings) or siblings[n-1] != node:
                return False

    attr_matchers = re.findall(r'\[([a-zA-Z0-9_-]+)(?:([^=]*)=["\']?([^"\']*)["\']?)?\]', simple_sel)
    simple_sel = re.sub(r'\[.*?\]', '', simple_sel)

    for attr_name, op, attr_val in attr_matchers:
        if attr_name not in node.attrs:
            return False
        curr_val = node.attrs[attr_name]
        if not op:
            continue
        elif op == "" and curr_val != attr_val:
            return False
        elif op == "^" and not curr_val.startswith(attr_val):
            return False
        elif op == "$" and not curr_val.endswith(attr_val):
            return False
        elif op == "*" and attr_val not in curr_val:
            return False
        elif op == "~" and attr_val not in curr_val.split():
            return False

    m_id = re.search(r'#([a-zA-Z0-9_-]+)', simple_sel)
    if m_id:
        req_id = m_id.group(1)
        if node.attrs.get("id") != req_id:
            return False
        simple_sel = simple_sel.replace(f"#{req_id}", "")

    classes = re.findall(r'\.([a-zA-Z0-9_-]+)', simple_sel)
    for c in classes:
        curr_classes = node.attrs.get("class", "").split()
        if c not in curr_classes:
            return False
        simple_sel = simple_sel.replace(f".{c}", "")

    tag = simple_sel.strip()
    if tag and tag != "*":
        if node.tag.lower() != tag.lower():
            return False

    return True

def node_matches_chain(node, chain):
    if not chain:
        return False

    idx = len(chain) - 1
    comb, simple = chain[idx]
    if not matches_simple_selector(node, simple):
        return False

    curr_node = node
    while idx > 0:
        comb, simple = chain[idx]
        prev_comb, prev_simple = chain[idx-1]

        if comb == ">":
            curr_node = curr_node.parent
            if not curr_node or not matches_simple_selector(curr_node, prev_simple):
                return False
        elif comb in (" ", None):
            matched_ancestor = None
            p = curr_node.parent
            while p and p.node_type == "element":
                if matches_simple_selector(p, prev_simple):
                    matched_ancestor = p
                    break
                p = p.parent
            if not matched_ancestor:
                return False
            curr_node = matched_ancestor
        elif comb == "+":
            if not curr_node.parent:
                return False
            sibs = [c for c in curr_node.parent.children if c.node_type == "element"]
            try:
                pos = sibs.index(curr_node)
                if pos == 0 or not matches_simple_selector(sibs[pos-1], prev_simple):
                    return False
                curr_node = sibs[pos-1]
            except ValueError:
                return False
        elif comb == "~":
            if not curr_node.parent:
                return False
            sibs = [c for c in curr_node.parent.children if c.node_type == "element"]
            try:
                pos = sibs.index(curr_node)
                matched_prev = None
                for i in range(pos - 1, -1, -1):
                    if matches_simple_selector(sibs[i], prev_simple):
                        matched_prev = sibs[i]
                        break
                if not matched_prev:
                    return False
                curr_node = matched_prev
            except ValueError:
                return False

        idx -= 1

    return True

def css_select(root, selector_str):
    parsed_groups = parse_css_selector(selector_str)
    if not parsed_groups:
        return []

    matched_nodes = []

    def traverse(node):
        if node.node_type == "element":
            for chain in parsed_groups:
                if node_matches_chain(node, chain):
                    matched_nodes.append(node)
                    break
        for c in node.children:
            traverse(c)

    traverse(root)
    return matched_nodes

# --- XPath Query Evaluator ---

def xpath_select(root, query_str):
    q = query_str.strip()
    if q.startswith("count(") and q.endswith(")"):
        inner = q[6:-1].strip()
        matches = xpath_select(root, inner)
        return str(len(matches))
    elif q.startswith("string(") and q.endswith(")"):
        inner = q[7:-1].strip()
        matches = xpath_select(root, inner)
        if matches:
            first = matches[0]
            if isinstance(first, tuple):
                node, is_attr, attr_name = first
                return node.attrs.get(attr_name, "")
            return first.inner_text()
        return ""

    steps = [s for s in re.split(r'(//|/)', q) if s]
    curr_nodes = [root]
    i = 0
    is_descendant = False

    while i < len(steps):
        step = steps[i]
        if step == "//":
            is_descendant = True
            i += 1
            continue
        elif step == "/":
            is_descendant = False
            i += 1
            continue

        next_nodes = []
        is_attr_step = step.startswith("@")
        attr_name = step[1:] if is_attr_step else None

        pred = None
        m_pred = re.search(r'\[(.*?)\]$', step)
        if m_pred:
            pred = m_pred.group(1).strip()
            step = step[:m_pred.start()].strip()

        if is_attr_step:
            for cn in curr_nodes:
                if cn.node_type == "element":
                    if attr_name == "*" or attr_name in cn.attrs:
                        next_nodes.append((cn, True, attr_name))
            curr_nodes = next_nodes
            i += 1
            continue

        candidates = []
        if is_descendant:
            def collect(n):
                candidates.append(n)
                for c in n.children:
                    collect(c)
            for cn in curr_nodes:
                for c in cn.children:
                    collect(c)
        else:
            for cn in curr_nodes:
                for c in cn.children:
                    candidates.append(c)

        for cand in candidates:
            if step == "text()":
                if cand.node_type == "text":
                    next_nodes.append(cand)
            elif step == "*" or (cand.node_type == "element" and cand.tag.lower() == step.lower()):
                if pred:
                    if pred.isdigit() or pred.startswith("position()="):
                        pass
                    elif pred.startswith("@"):
                        p_attr = pred[1:]
                        if "=" in p_attr:
                            pk, pv = p_attr.split("=", 1)
                            pv = pv.strip("'\"")
                            if cand.attrs.get(pk) != pv:
                                continue
                        else:
                            if p_attr not in cand.attrs:
                                continue
                    next_nodes.append(cand)
                else:
                    next_nodes.append(cand)

        if pred and (pred.isdigit() or pred.startswith("position()=")):
            target_pos = int(pred) if pred.isdigit() else int(pred.split("=")[1])
            if target_pos <= len(next_nodes):
                next_nodes = [next_nodes[target_pos - 1]]
            else:
                next_nodes = []

        curr_nodes = next_nodes
        i += 1

    return curr_nodes

# --- Main Entry Point ---

def process_content(content, opts, is_stdin=False):
    if not content and is_stdin:
        sys.stderr.write("Error: unknown content type: 3\n")
        sys.exit(1)

    trimmed = content.lstrip()
    is_json_input = False
    is_html_input = opts.html

    if not is_html_input and not opts.json:
        if trimmed.startswith("{") or trimmed.startswith("["):
            is_json_input = True
        elif trimmed.lower().startswith("<!doctype html") or trimmed.lower().startswith("<html"):
            is_html_input = True

    color_enabled = False
    if opts.color:
        color_enabled = True
    elif not opts.no_color and sys.stdout.isatty():
        color_enabled = True

    if opts.xpath or opts.extract:
        xp_query = opts.xpath or opts.extract
        is_extract = bool(opts.extract)

        try:
            root = parse_xml(content) if not is_html_input else parse_html(content)
        except Exception:
            sys.stderr.write("Error: unable to parse the XPath query\n")
            sys.exit(1)

        try:
            results = xpath_select(root, xp_query)
        except Exception:
            sys.stderr.write("Error: unable to parse the XPath query\n")
            sys.exit(1)

        if isinstance(results, str):
            print(results)
            return

        if is_extract and results:
            results = [results[0]]

        out_lines = []
        indent_unit = "\t" if opts.tab else (" " * opts.indent)

        for res in results:
            if isinstance(res, tuple):
                node, is_attr, attr_name = res
                val = node.attrs.get(attr_name, "")
                if opts.node:
                    out_lines.append(f"<{attr_name}>{val}</{attr_name}>")
                else:
                    out_lines.append(val)
            elif isinstance(res, DOMNode):
                if opts.node:
                    fmt = format_node(res, is_html_input, indent_unit, 0).strip()
                    out_lines.append(fmt)
                else:
                    txt = res.inner_text().strip()
                    out_lines.append(txt)

        final_out = "\n".join(out_lines) + ("\n" if out_lines else "")
        if color_enabled and opts.node:
            final_out = colorize_xml_html(final_out)
        sys.stdout.write(final_out)
        return

    if opts.query:
        try:
            root = parse_html(content) if is_html_input else parse_xml(content)
        except Exception:
            sys.stdout.write("\n")
            return

        matched_nodes = css_select(root, opts.query)
        indent_unit = "\t" if opts.tab else (" " * opts.indent)
        out_lines = []

        for node in matched_nodes:
            if opts.attr:
                val = node.attrs.get(opts.attr, "")
                out_lines.append(val)
            elif opts.node:
                fmt = format_node(node, is_html_input, indent_unit, 0).strip()
                out_lines.append(fmt)
            else:
                out_lines.append(node.inner_text())

        final_out = "\n".join(out_lines) + ("\n" if out_lines else "")
        if color_enabled and opts.node:
            final_out = colorize_xml_html(final_out)
